<?php

declare(strict_types=1);

namespace Sentinel\Services;

use DateTimeImmutable;
use PDOException;
use Sentinel\Core\HttpException;

final class AttendanceManagementService
{
    private const STATUSES=['PRESENT','LATE','ABSENT','OFF_DUTY']; private const SOURCES=['MOBILE_APP','BIOMETRIC','MANUAL','API'];
    public function __construct(private readonly \Sentinel\Repositories\AttendanceRepository $attendance){}
    public function listAttendance():array{try{return$this->attendance->listForCompany();}catch(PDOException$e){throw new HttpException(503,'Attendance service unavailable.','attendance_service_unavailable',$e);}}
    public function getAttendance(string$id):array{try{$r=$this->attendance->findByIdForCompany($id);}catch(PDOException$e){throw new HttpException(503,'Attendance service unavailable.','attendance_service_unavailable',$e);}if($r===null)throw HttpException::notFound('Attendance not found.','attendance_not_found');return$r;}
    public function createAttendance(array$input):array{$d=$this->validate($input,false);$this->refs($d);$this->times($d);try{if($this->attendance->attendanceExistsForEmployeeDate((string)$d['employee_id'],$d['shift_date']))throw HttpException::conflict('Attendance record already exists.','attendance_conflict');return$this->attendance->createForCompany($d);}catch(PDOException$e){throw new HttpException(503,'Attendance service unavailable.','attendance_service_unavailable',$e);}}
    public function updateAttendance(string$id,array$input):array{$existing=$this->getAttendance($id);$d=$this->validate($input,true);$effective=array_merge($existing,$d);$this->refs($effective);$this->times($effective);$this->validateClockInUpdate($existing,$d);try{if($this->attendance->attendanceExistsForEmployeeDate((string)$effective['employee_id'],$effective['shift_date'],$id))throw HttpException::conflict('Attendance record already exists.','attendance_conflict');$r=$this->attendance->updateForCompany($id,$d);}catch(PDOException$e){throw new HttpException(503,'Attendance service unavailable.','attendance_service_unavailable',$e);}if($r===null)throw HttpException::notFound('Attendance not found.','attendance_not_found');return$r;}
    private function validate(array$i,bool$update):array{$d=[];foreach(['employee_id','shift_assignment_id','contract_id','site_id','post_id','shift_date','clock_in_at','clock_out_at','attendance_status','source','notes']as$f)if(array_key_exists($f,$i))$d[$f]=$i[$f];foreach(['employee_id','shift_assignment_id','contract_id','site_id','post_id']as$f)if(array_key_exists($f,$d)&&$d[$f]!==null)$d[$f]=$this->positive($d[$f],$f);foreach(['shift_date','clock_in_at','clock_out_at']as$f)if(array_key_exists($f,$d)&&$d[$f]!==null)$d[$f]=$this->date($d[$f],$f);if(isset($d['attendance_status'])&&(!is_string($d['attendance_status'])||!in_array($d['attendance_status'],self::STATUSES,true)))throw HttpException::unprocessable('Attendance status is invalid.','invalid_attendance_status');if(isset($d['source'])&&(!is_string($d['source'])||!in_array($d['source'],self::SOURCES,true)))throw HttpException::unprocessable('Attendance source is invalid.','invalid_attendance_source');if(!$update)foreach(['employee_id','shift_date']as$r)if(!array_key_exists($r,$d))throw HttpException::unprocessable(ucfirst(str_replace('_',' ',$r)).' is required.','invalid_'.$r);return$d;}
    private function refs(array$d):void{try{if(!$this->attendance->employeeBelongsToCompany((string)$d['employee_id']))throw HttpException::notFound('Employee not found.','employee_not_found');if(isset($d['site_id'])&&!$this->attendance->siteBelongsToCompany((string)$d['site_id']))throw HttpException::notFound('Site not found.','site_not_found');if(isset($d['contract_id'])&&!$this->attendance->contractBelongsToCompany((string)$d['contract_id']))throw HttpException::notFound('Contract not found.','contract_not_found');if(isset($d['post_id'])&&!$this->attendance->postBelongsToCompany((string)$d['post_id']))throw HttpException::notFound('Post not found.','post_not_found');if(isset($d['shift_assignment_id'])){if(!$this->attendance->shiftBelongsToCompany((string)$d['shift_assignment_id']))throw HttpException::notFound('Shift assignment not found.','shift_assignment_not_found');$s=$this->attendance->shiftDetails((string)$d['shift_assignment_id']);if((string)$s['employee_id']!==(string)$d['employee_id']||($s['site_id']!==null&&isset($d['site_id'])&&(string)$s['site_id']!==(string)$d['site_id']))throw HttpException::unprocessable('Attendance relationship is invalid.','invalid_attendance_relationship');}}catch(PDOException$e){throw new HttpException(503,'Attendance service unavailable.','attendance_service_unavailable',$e);}}
    private function times(array$d):void{$in=$this->parse($d['clock_in_at']??null);$out=$this->parse($d['clock_out_at']??null);if($in!==null&&$out!==null&&$out<$in)throw HttpException::unprocessable('Clock-out must not precede clock-in.','invalid_attendance_timestamps');}
    private function validateClockInUpdate(array$existing,array$patch):void{if(!array_key_exists('clock_in_at',$patch))return;$existingClockIn=$this->parse($existing['clock_in_at']??null);$incomingClockIn=$this->parse($patch['clock_in_at']);if($existingClockIn===null||$incomingClockIn===null)return;if($existingClockIn->format('Y-m-d H:i:s')!==$incomingClockIn->format('Y-m-d H:i:s'))throw HttpException::unprocessable('Attendance is already clocked in.','attendance_already_clocked_in');}
    private function positive(mixed$v,string$f):int{if((!is_int($v)&&!(is_string($v)&&ctype_digit($v)))||(int)$v<1)throw HttpException::unprocessable(ucfirst($f).' is invalid.','invalid_'.$f);return(int)$v;}
    private function date(mixed$v,string$f):string{if(!is_string($v)||($f==='shift_date'?$this->parseDate($v)===null:$this->parse($v)===null))throw HttpException::unprocessable(ucfirst(str_replace('_',' ',$f)).' is invalid.','invalid_'.$f);return$v;}
    private function parseDate(string$v):?DateTimeImmutable{$parsed=DateTimeImmutable::createFromFormat('!Y-m-d',$v);return$parsed!==false&&$parsed->format('Y-m-d')===$v?$parsed:null;}
    private function parse(mixed$v):?DateTimeImmutable{if(!is_string($v)||$v==='')return null;try{return new DateTimeImmutable($v);}catch(\Throwable){return null;}}
}